import React, { useState } from 'react';
import './Recharge.css';

function Recharge() {
  const [selectedAmount, setSelectedAmount] = useState(50000);
  const [paymentMethod, setPaymentMethod] = useState('bank');
  const [userInfo, setUserInfo] = useState({
    email: '',
    name: ''
  });

  const rechargePackages = [
    { id: 1, amount: 50000, bonus: 0, popular: false },
    { id: 2, amount: 100000, bonus: 5000, popular: false },
    { id: 3, amount: 200000, bonus: 20000, popular: true },
    { id: 4, amount: 500000, bonus: 60000, popular: false },
    { id: 5, amount: 1000000, bonus: 150000, popular: false },
  ];

  const paymentMethods = [
    { id: 'bank', name: '💳 Chuyển Khoản Ngân Hàng', icon: '🏦' },
    { id: 'momo', name: '📱 Ví MoMo', icon: '📱' },
    { id: 'zalopay', name: '💰 ZaloPay', icon: '💰' },
    { id: 'vietqr', name: '🔗 VietQR', icon: '🔗' },
  ];

  const handleRecharge = () => {
    if (!userInfo.email || !userInfo.name) {
      alert('Vui lòng điền đầy đủ thông tin!');
      return;
    }
    alert(`Nạp ${selectedAmount.toLocaleString('vi-VN')}đ thành công!`);
  };

  return (
    <div className="recharge-container">
      <h1>💰 NẠP TIỀN VÀO TÀI KHOẢN</h1>

      <div className="recharge-content">
        <div className="recharge-left">
          <h2>Chọn Số Tiền</h2>
          <div className="packages-grid">
            {rechargePackages.map(pkg => (
              <div
                key={pkg.id}
                className={`package-card ${selectedAmount === pkg.amount ? 'active' : ''} ${pkg.popular ? 'popular' : ''}`}
                onClick={() => setSelectedAmount(pkg.amount)}
              >
                {pkg.popular && <span className="popular-badge">⭐ PHỔ BIẾN</span>}
                <div className="amount">{pkg.amount.toLocaleString('vi-VN')}</div>
                <div className="currency">VND</div>
                {pkg.bonus > 0 && (
                  <div className="bonus">+ {pkg.bonus.toLocaleString('vi-VN')} bonus</div>
                )}
              </div>
            ))}
          </div>

          <h2 style={{ marginTop: '2rem' }}>Phương Thức Thanh Toán</h2>
          <div className="payment-methods">
            {paymentMethods.map(method => (
              <div
                key={method.id}
                className={`payment-method ${paymentMethod === method.id ? 'active' : ''}`}
                onClick={() => setPaymentMethod(method.id)}
              >
                <span className="icon">{method.icon}</span>
                <span>{method.name}</span>
              </div>
            ))}
          </div>
        </div>

        <div className="recharge-right">
          <div className="summary-card">
            <h2>Thông Tin Nạp Tiền</h2>

            <div className="form-group">
              <label>Email:</label>
              <input
                type="email"
                placeholder="Nhập email của bạn"
                value={userInfo.email}
                onChange={(e) => setUserInfo({ ...userInfo, email: e.target.value })}
              />
            </div>

            <div className="form-group">
              <label>Tên Hiển Thị:</label>
              <input
                type="text"
                placeholder="Nhập tên của bạn"
                value={userInfo.name}
                onChange={(e) => setUserInfo({ ...userInfo, name: e.target.value })}
              />
            </div>

            <div className="summary-line">
              <span>Số Tiền:</span>
              <strong>{selectedAmount.toLocaleString('vi-VN')} đ</strong>
            </div>

            <div className="summary-line">
              <span>Phương Thức:</span>
              <strong>
                {paymentMethods.find(m => m.id === paymentMethod)?.name.replace(/[📱💳💰🔗]/g, '').trim()}
              </strong>
            </div>

            <div className="summary-line bonus">
              <span>Tiền Thưởng:</span>
              <strong>
                {rechargePackages.find(p => p.amount === selectedAmount)?.bonus.toLocaleString('vi-VN')} đ
              </strong>
            </div>

            <div className="summary-line total">
              <span>Tổng Cộng:</span>
              <strong>
                {(selectedAmount + (rechargePackages.find(p => p.amount === selectedAmount)?.bonus || 0)).toLocaleString('vi-VN')} đ
              </strong>
            </div>

            <button className="recharge-btn" onClick={handleRecharge}>
              💳 TIẾN HÀNH THANH TOÁN
            </button>

            <div className="info-box">
              <h4>ℹ️ Lưu Ý Quan Trọng</h4>
              <ul>
                <li>✓ Tiền thưởng sẽ được cộng ngay sau thanh toán</li>
                <li>✓ Không hoàn lại nếu bạn nạp sai tài khoản</li>
                <li>✓ Hỗ trợ 24/7 nếu có vấn đề</li>
                <li>✓ Tiền sẽ hiển thị trong vòng 1-5 phút</li>
              </ul>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Recharge;
